svg.script:
const BASE = "https:/" + "/cdn.jsdelivr.net/gh/jaromaz/jslinux-mobile@master/";
const frame = document.getElementById("linux_frame");

// Safe storage shim in case Chrome blocks cookies/localStorage inside an SVG iframe
const shim = `<base href="${BASE}" /><script>
  try { window.localStorage.getItem("t"); } catch (e) {
    const mem = {};
    Object.defineProperty(window, "localStorage", { value: {
      getItem: k => mem[k] || null,
      setItem: (k, v) => { mem[k] = String(v); },
      removeItem: k => { delete mem[k]; },
      clear: () => { for (const k in mem) delete mem[k]; }
    }});
  }
  try { document.cookie; } catch (e) {
    let c = "";
    Object.defineProperty(document, "cookie", { get: () => c, set: v => { c = v; } });
  }

       // Capture JSLinux's exact internal keyboard handler as it registers
  let jslinuxKeyHandler = null;
  const origAdd = EventTarget.prototype.addEventListener;
  EventTarget.prototype.addEventListener = function(type, fn, opts) {
    if ((type === "keypress" || type === "keydown") && typeof fn === "function" && !jslinuxKeyHandler) {
      jslinuxKeyHandler = fn;
    }
    return origAdd.call(this, type, fn, opts);
  };

  // Feed clipboard text directly into JSLinux's captured handler on Ctrl+V
  origAdd.call(window, "keydown", async (e) => {
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "v") {
      e.preventDefault();
      e.stopImmediatePropagation();
      try {
        const text = await navigator.clipboard.readText();
        if (!text || !jslinuxKeyHandler) return;
        const clean = text.replace(/\r\n/g, "\n");
        let idx = 0;

        const typer = setInterval(() => {
          if (idx >= clean.length) {
            clearInterval(typer);
            return;
          }
          const ch = clean[idx++];
          const isEnter = ch === "\n";
          const code = isEnter ? 13 : ch.charCodeAt(0);
          jslinuxKeyHandler({
            type: "keypress",
            key: isEnter ? "Enter" : ch,
            charCode: code,
            keyCode: code,
            which: code,
            ctrlKey: false,
            altKey: false,
            metaKey: false,
            shiftKey: false,
            preventDefault: () => {},
            stopPropagation: () => {}
          });
        }, 15);
      } catch (err) {
        console.warn("Clipboard paste blocked:", err);
      }
    }
  }, true);






<\/script>`;

fetch(BASE + "index.html")
  .then(res => {
    if (!res.ok) throw new Error("HTTP " + res.status);
    return res.text();
  })
  .then(html => {
    const injected = html.replace(/<head[^>]*>/i, match => match + shim);
    const doc = frame.contentDocument || frame.contentWindow.document;
    doc.open();
    doc.write(injected);
    doc.close();
  })
  .catch(err => {
    const doc = frame.contentDocument || frame.contentWindow.document;
    doc.open();
    doc.write('<body style="background:#000;color:#0f0;font-family:monospace;padding:16px;">Error: ' + err.message + '</body>');
    doc.close();
  });
